import { useState } from 'react';
import './App.css';
import SingleCheck from './components/SingleCheck';
import BulkVerify from './components/BulkVerify';

const TABS = [
  { id: 'single', label: 'Single check', desc: 'Verify one email instantly' },
  { id: 'bulk', label: 'Bulk verify', desc: 'Upload CSV or paste a list' },
];

export default function App() {
  const [tab, setTab] = useState('single');

  return (
    <div style={{ minHeight: '100vh', background: 'var(--bg)' }}>

      {/* Top nav */}
      <div style={{ borderBottom: '1.5px solid var(--border)', background: 'var(--bg2)', position: 'sticky', top: 0, zIndex: 10, backdropFilter: 'blur(8px)' }}>
        <div style={{ maxWidth: 820, margin: '0 auto', padding: '0 28px', height: 58, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
            <div style={{ width: 32, height: 32, background: 'var(--accent)', borderRadius: 8, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontSize: 15 }}>✉</div>
            <span style={{ fontFamily: 'Syne', fontWeight: 700, fontSize: 17, letterSpacing: '-0.02em' }}>MailClean</span>
            <span style={{ background: 'var(--bg3)', border: '1px solid var(--border)', borderRadius: 5, padding: '1px 7px', fontSize: 10, fontFamily: 'DM Mono', color: 'var(--text-dim)' }}>v1.0</span>
          </div>
          <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
            <div style={{ width: 8, height: 8, borderRadius: '50%', background: '#22c55e' }}></div>
            <span style={{ fontSize: 12, color: 'var(--text-muted)', fontFamily: 'DM Mono' }}>API connected</span>
          </div>
        </div>
      </div>

      <div style={{ maxWidth: 820, margin: '0 auto', padding: '0 28px 80px' }}>

        {/* Hero */}
        <div style={{ padding: '52px 0 40px', textAlign: 'center' }}>
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, background: 'var(--bg3)', border: '1px solid var(--border)', borderRadius: 20, padding: '5px 14px', marginBottom: 20, fontSize: 12, color: 'var(--text-muted)', fontFamily: 'DM Mono' }}>
            ⚡ SMTP · MX · catch-all · disposable · risk scoring
          </div>
          <h1 style={{ fontSize: 42, fontWeight: 700, letterSpacing: '-0.04em', lineHeight: 1.1, marginBottom: 14, color: 'var(--text)' }}>
            Clean your email list<br />
            <span style={{ color: 'var(--text-dim)' }}>before you hit send.</span>
          </h1>
          <p style={{ color: 'var(--text-muted)', fontSize: 15, maxWidth: 440, margin: '0 auto' }}>
            Full deliverability check in seconds. Stop wasting sends on dead addresses.
          </p>
        </div>

        {/* Tab switcher */}
        <div style={{ display: 'flex', gap: 12, marginBottom: 32, justifyContent: 'center' }}>
          {TABS.map(t => (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              style={{
                background: tab === t.id ? 'var(--accent)' : 'var(--bg2)',
                color: tab === t.id ? '#fff' : 'var(--text-muted)',
                border: `1.5px solid ${tab === t.id ? 'var(--accent)' : 'var(--border)'}`,
                padding: '10px 24px',
                borderRadius: 'var(--radius)',
                fontFamily: 'Syne',
                fontWeight: 600,
                fontSize: 13,
                cursor: 'pointer',
                transition: 'all 0.15s',
                boxShadow: tab === t.id ? 'var(--shadow-md)' : 'var(--shadow)',
              }}
            >
              {t.label}
            </button>
          ))}
        </div>

        {/* Main card */}
        <div className="card animate-in" key={tab} style={{ borderRadius: 'var(--radius-lg)', padding: '32px 36px' }}>
          {tab === 'single' && <SingleCheck />}
          {tab === 'bulk' && <BulkVerify />}
        </div>

        {/* Stats row */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 14, marginTop: 24 }}>
          {[
            { label: 'Verification speed', value: '2k–8k/hr', sub: 'with 30 threads' },
            { label: 'Detection layers', value: '6 checks', sub: 'per email address' },
            { label: 'Max batch size', value: '50,000', sub: 'emails per upload' },
          ].map(s => (
            <div key={s.label} style={{ background: 'var(--bg2)', border: '1.5px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '18px 20px', boxShadow: 'var(--shadow)' }}>
              <div style={{ fontFamily: 'Syne', fontSize: 22, fontWeight: 700, letterSpacing: '-0.02em', marginBottom: 2 }}>{s.value}</div>
              <div style={{ fontSize: 12, color: 'var(--text-muted)', marginBottom: 1 }}>{s.label}</div>
              <div style={{ fontSize: 11, color: 'var(--text-dim)', fontFamily: 'DM Mono' }}>{s.sub}</div>
            </div>
          ))}
        </div>

        {/* Footer */}
        <div style={{ marginTop: 40, paddingTop: 20, borderTop: '1.5px solid var(--border)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{ fontSize: 11, color: 'var(--text-dim)', fontFamily: 'DM Mono' }}>
            {process.env.REACT_APP_API_URL || 'http://127.0.0.1:8000'}
          </span>
          <span style={{ fontSize: 11, color: 'var(--text-dim)' }}>MailClean © {new Date().getFullYear()}</span>
        </div>
      </div>
    </div>
  );
}
